create or replace function app.set_finance_invoice_item_estimated_cost(p_invoice_item_id uuid,p_estimated_unit_cost numeric) returns uuid language plpgsql security definer set search_path='' as $$declare v_item public.finance_invoice_items%rowtype;v_invoice public.finance_invoices%rowtype;begin if not app.has_permission('finance_invoices.update_draft') then raise exception 'Missing permission: finance_invoices.update_draft' using errcode='42501';end if;if p_estimated_unit_cost is null or p_estimated_unit_cost<0 then raise exception 'Estimated unit cost must be nonnegative.' using errcode='22023';end if;select * into v_item from public.finance_invoice_items where id=p_invoice_item_id for update;if not found then raise exception 'Invoice item not found.' using errcode='P0002';end if;select * into v_invoice from public.finance_invoices where id=v_item.invoice_id for update;if v_invoice.status<>'draft' then raise exception 'Estimated HPP can only be changed while invoice is draft.' using errcode='23514';end if;update public.finance_invoice_items set estimated_unit_cost=p_estimated_unit_cost,estimated_cost_total=round(p_estimated_unit_cost*v_item.quantity,2) where id=p_invoice_item_id;insert into public.audit_logs(actor_user_id,actor_type,action,entity_type,entity_id,summary,changes) values(auth.uid(),app.current_actor_type(),'finance.invoice_hpp_estimate_updated','finance_invoice_item',p_invoice_item_id,'Estimated HPP updated.',jsonb_build_object('invoice_id',v_item.invoice_id,'estimated_unit_cost',p_estimated_unit_cost,'estimated_cost_total',round(p_estimated_unit_cost*v_item.quantity,2)));return p_invoice_item_id;end$$;
create or replace function app.record_linked_finance_expense(p_expense_on date,p_category text,p_vendor_name text,p_description text,p_amount numeric,p_tax_amount numeric,p_cost_class public.finance_cost_class,p_invoice_id uuid,p_receipt_asset_id uuid,p_reference text,p_payment_method text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$declare v_id uuid;v_existing public.finance_expenses%rowtype;v_tax numeric:=coalesce(p_tax_amount,0);begin if not app.has_permission('finance_expenses.record') then raise exception 'Missing permission: finance_expenses.record' using errcode='42501';end if;if p_expense_on is null or p_expense_on>current_date then raise exception 'Expense date is invalid.' using errcode='23514';end if;if p_amount is null or p_amount<=0 or v_tax<0 or v_tax>p_amount then raise exception 'Expense/tax amount is invalid.' using errcode='23514';end if;if length(btrim(coalesce(p_category,'')))<2 or length(btrim(coalesce(p_description,'')))<3 then raise exception 'Expense category/description is required.' using errcode='23514';end if;if length(btrim(coalesce(p_idempotency_key,'')))<8 then raise exception 'Idempotency key is required.' using errcode='23514';end if;if p_invoice_id is not null and not exists(select 1 from public.finance_invoices where id=p_invoice_id) then raise exception 'Linked invoice not found.' using errcode='23503';end if;if p_cost_class='direct_cost' and p_invoice_id is null then raise exception 'Direct cost/HPP must be linked to an invoice.' using errcode='23514';end if;select * into v_existing from public.finance_expenses where idempotency_key=p_idempotency_key;if found then if v_existing.expense_on=p_expense_on and v_existing.total_amount=p_amount and v_existing.receipt_asset_id=p_receipt_asset_id and v_existing.invoice_id is not distinct from p_invoice_id and v_existing.cost_class=p_cost_class then return v_existing.id;end if;raise exception 'Idempotency key was already used with different expense data.' using errcode='23505';end if;if not exists(select 1 from public.media_assets a where a.id=p_receipt_asset_id and a.bucket='company-documents' and a.path like 'finance/expenses/%' and a.visibility='restricted' and a.finalized_at is not null) then raise exception 'Finalized expense receipt is required.' using errcode='23503';end if;if exists(select 1 from public.financial_periods fp join public.financial_reports fr on fr.financial_period_id=fp.id where p_expense_on between fp.starts_on and fp.ends_on and fr.status in('review','approved','published')) then raise exception 'Expense period is already under financial report review or publication.' using errcode='42501';end if;insert into public.finance_expenses(reference,status,expense_on,category,vendor_name,description,quantity,unit_price,tax_amount,total_amount,currency,payment_method,receipt_asset_id,recorded_by,idempotency_key,cost_class,invoice_id) values(coalesce(nullif(btrim(coalesce(p_reference,'')),''),'EXP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),'recorded',p_expense_on,btrim(p_category),nullif(btrim(coalesce(p_vendor_name,'')),''),btrim(p_description),1,p_amount-v_tax,v_tax,p_amount,'IDR',coalesce(nullif(btrim(coalesce(p_payment_method,'')),''),'Transfer'),p_receipt_asset_id,auth.uid(),p_idempotency_key,p_cost_class,p_invoice_id) returning id into v_id;insert into public.audit_logs(actor_user_id,actor_type,action,entity_type,entity_id,summary,changes) values(auth.uid(),app.current_actor_type(),'finance.expense_recorded','finance_expense',v_id,'Expense recorded with accounting classification.',jsonb_build_object('invoice_id',p_invoice_id,'cost_class',p_cost_class,'tax_amount',v_tax,'total_amount',p_amount));return v_id;end$$;revoke all on function app.set_finance_invoice_item_estimated_cost(uuid,numeric) from public,anon;grant execute on function app.set_finance_invoice_item_estimated_cost(uuid,numeric) to authenticated;revoke all on function app.record_linked_finance_expense(date,text,text,text,numeric,numeric,public.finance_cost_class,uuid,uuid,text,text,text) from public,anon;grant execute on function app.record_linked_finance_expense(date,text,text,text,numeric,numeric,public.finance_cost_class,uuid,uuid,text,text,text) to authenticated;